INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (126, 175, 'Self adhesive labels in rolls', '../upload/image/20181226/20181226151133_76448.jpg', '<p></p><p>Self adhesive labels in rolls</p> <p>we manufacture all kinds of Coated paper material self-adhesive labels in rolls, <br/> 1.) material:80G semi-glossy coated paper, color: white, non-printed . coated glue and self-adhesive size:80G*32MM*40MM (three pieces per line) ,5000pieces/roll 16rolls/carton<br/> 2.) Self-adhesive labels, Coated paper material self-adhesive label, material:80G semi-glossy coated paper, coated glue and self-adhesive size:80G*50MM*70MM (two pieces per line) ,2000pieces/roll 16rolls/carton<br/> 3.) Self Labels - Semi Gloss - 100mm x 70 mm - 1000 pieces/roll <br/> 4.) Barcode printer (Fight Code Machine),High-speed printer for printing declaration such as: Datamax DMX-E-4304B (without Ethernet interface),Datamax DMX-E-4204B (without Ethernet interface),Zebra GT810 200dpi (with/have Ethernet interface)<br/> 5.) all kinds of self adhesive label in difference materials.</p> <p></p><div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Coated paper labels are commonly used materials for barcode printers to print labels, and their thickness is generally around 80g. It is a very common printing material in the packaging and printing industry. It is a high-grade printing paper made of base paper coated with white paint. The surface of the paper is smooth and the whiteness is high. After packaging and printing processing, delicate and clear patterns can be obtained. and text, generally divided into ordinary coated paper and mirror coated paper </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Product features: semi-gloss white coated paper, basic weight 80g/square meter, surface substrate thickness 72um, overall label thickness 147um, use temperature range -50~+90 degrees, low labeling temperature +7 degrees </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Scope of application: Widely used in supermarkets, inventory management, clothing tags, industrial production lines, suitable for promotion and semi-gloss color printing in industry. Typical applications such as cosmetic labels, drug labels and food industry labels. Can be attached to most substrates Flat and simple curved surfaces, including cardboard, plastic film. </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Product features: smooth and bright white coated paper with polished surface, basic weight 80g/square meter, overall label thickness 165um, use temperature range -50~+90 degrees, low labeling temperature +7 degrees </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Scope of application: Widely used in high-gloss color label printing, typical applications such as cosmetic labels, pharmaceutical labels, food labels and promotional labels, etc. Can be applied to flat and simple curved surfaces of most substrates, including cardboard, plastic film and HDPE containers. </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (126, 208, 'Self-adhesive labels and Barcode printer', '../upload/image/20181226/20181226151107_97352.jpg', '<p></p><p>Self-adhesive labels and Barcode printer</p> <p>we manufacture all kinds of Coated paper material self-adhesive labels in rolls, 1.) material:80G semi-glossy coated paper, color: white, non-printed . coated glue and self-adhesive size:80G*32MM*40MM (three pieces per line) ,5000pieces/roll 16rolls/carton<br/> 2.) Self-adhesive labels, Coated paper material self-adhesive label, material:80G semi-glossy coated paper, coated glue and self-adhesive size:80G*50MM*70MM (two pieces per line) ,2000pieces/roll 16rolls/carton<br/> 3.) Self Labels - Semi Gloss - 100mm x 70 mm - 1000 pieces/roll <br/> 4.) Barcode printer (Fight Code Machine),High-speed printer for printing declaration such as: Datamax DMX-E-4304B (without Ethernet interface),Datamax DMX-E-4204B (without Ethernet interface),Zebra GT810 200dpi (with/have Ethernet interface)</p> <p></p><div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Coated paper labels are commonly used materials for barcode printers to print labels, and their thickness is generally around 80g. It is a very common printing material in the packaging and printing industry. It is a high-grade printing paper made of base paper coated with white paint. The surface of the paper is smooth and the whiteness is high. After packaging and printing processing, delicate and clear patterns can be obtained. and text, generally divided into ordinary coated paper and mirror coated paper </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Product features: semi-gloss white coated paper, basic weight 80g/square meter, surface substrate thickness 72um, overall label thickness 147um, use temperature range -50~+90 degrees, low labeling temperature +7 degrees </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Scope of application: Widely used in supermarkets, inventory management, clothing tags, industrial production lines, suitable for promotion and semi-gloss color printing in industry. Typical applications such as cosmetic labels, drug labels and food industry labels. Can be attached to most substrates Flat and simple curved surfaces, including cardboard, plastic film. </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Product features: smooth and bright white coated paper with polished surface, basic weight 80g/square meter, overall label thickness 165um, use temperature range -50~+90 degrees, low labeling temperature +7 degrees </div> <div style="color:#008000;font-family:Calibri;background-color:#FFFFFF;font-size:14px;"> Scope of application: Widely used in high-gloss color label printing, typical applications such as cosmetic labels, pharmaceutical labels, food labels and promotional labels, etc. Can be applied to flat and simple curved surfaces of most substrates, including cardboard, plastic film and HDPE containers. </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (126, 442, 'BOPP White Gloss labels', '../', '<p><div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> BOPP White Gloss labels </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> Usage Final usage: labels in food industry Film Width: 108 cm (2 x 20 cm, 2 x 26,6 cm, 1 x 16,6 cm) Roll length: 2000 m Quantity: approx. 5 t/month </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> Face Material Description: White polypropylene film with glossy print receptive top coating. Basis Weight: 57 g/m² ISO 536 Caliper: 60 μm ISO 534 </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> ADHESIVE Rubber-resin hot-melt, permanent adhesive. Typical technical values: Initial tack: 14 N (FTM 9) FINAT FTM 9 glass Adhesion 180°:13 N/AT/PT (FTM 1) FINAT FTM 1 glass Application temp. min.: -5 °C Service temp.: -40 °C - +50 °C </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> SILICON RANGE Description: White, wood-free, transparent, glassine, backing paper. One side siliconised. Peeling: Standard Basis Weight (g/m2): 61 Caliper (μm): 52 Tensile Strength MD (kN/m): ≥5,3 Tensile Strength CD (kN/m): ≥2,4 </div></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (126, 443, 'BOPP White Gloss labels', '../', '<p><div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> BOPP White Gloss labels </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> Usage Final usage: labels in food industry Film Width: 108 cm (2 x 20 cm, 2 x 26,6 cm, 1 x 16,6 cm) Roll length: 2000 m Quantity: approx. 5 t/month </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> Face Material Description: White polypropylene film with glossy print receptive top coating. Basis Weight: 57 g/m² ISO 536 Caliper: 60 μm ISO 534 </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> ADHESIVE Rubber-resin hot-melt, permanent adhesive. Typical technical values: Initial tack: 14 N (FTM 9) FINAT FTM 9 glass Adhesion 180°:13 N/AT/PT (FTM 1) FINAT FTM 1 glass Application temp. min.: -5 °C Service temp.: -40 °C - +50 °C </div> <div style="color:#008000;font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> SILICON RANGE Description: White, wood-free, transparent, glassine, backing paper. One side siliconised. Peeling: Standard Basis Weight (g/m2): 61 Caliper (μm): 52 Tensile Strength MD (kN/m): ≥5,3 Tensile Strength CD (kN/m): ≥2,4 </div></p>', '2026-09-06 20:58:45');